def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the color used for full-width and full-height separators.
    row_lines = [r for r in range(h) if len(set(grid[r])) == 1]
    col_lines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    sep = grid[row_lines[0]][0]

    row_cuts = [-1] + row_lines + [h]
    col_cuts = [-1] + col_lines + [w]
    row_spans = [(row_cuts[i] + 1, row_cuts[i + 1])
                 for i in range(len(row_cuts) - 1)]
    col_spans = [(col_cuts[i] + 1, col_cuts[i + 1])
                 for i in range(len(col_cuts) - 1)]

    # Locate the stencil: the occupied tile with the most cells.
    best = None
    best_count = -1
    for ri, (r0, r1) in enumerate(row_spans):
        for ci, (c0, c1) in enumerate(col_spans):
            cells = [(r - r0, c - c0, grid[r][c])
                     for r in range(r0, r1) for c in range(c0, c1)
                     if grid[r][c] != 0]
            if len(cells) > best_count:
                best_count = len(cells)
                best = (ri, ci, cells)

    stencil_ri, _, stencil_cells = best
    mask = [(dr, dc) for dr, dc, _ in stencil_cells]
    out = [[0] * w for _ in range(h)]

    # Preserve separator lines.
    for r in row_lines:
        out[r] = grid[r][:]
    for c in col_lines:
        for r in range(h):
            out[r][c] = sep

    # Copy the stencil into each tile, colored by that band's marker.
    for ri, (r0, r1) in enumerate(row_spans):
        c0, c1 = col_spans[0]
        marker_colors = {grid[r][c] for r in range(r0, r1)
                         for c in range(c0, c1) if grid[r][c] != 0}
        color = next(iter(marker_colors))
        for c0, c1 in col_spans:
            for dr, dc in mask:
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color

    return out
